// The Dart offline assistant must answer exactly like the Python backend rules engine.
// Fixtures are generated by backend/scripts/make_parity_fixtures.py.
import 'dart:convert';
import 'dart:io';

import 'package:cartcloser_ai/core/engine/assistant_rules.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final copy = jsonDecode(File('assets/seed/assistant_copy.json').readAsStringSync()) as Map<String, dynamic>;
  final seed = jsonDecode(File('assets/seed/demo_seed.json').readAsStringSync()) as Map<String, dynamic>;
  final fixtures = jsonDecode(File('test/fixtures/parity_fixtures.json').readAsStringSync()) as List;
  final rules = AssistantRules(copy);
  final catalog = [
    for (final p in seed['products'] as List)
      {
        ...Map<String, dynamic>.from(p),
        'variants': [for (final v in p['variants'] as List) {'size': v[0], 'stock': v[1]}],
      }
  ];
  final byId = {for (final p in catalog) p['id'] as String: p};

  test('seed assets match the shared /seed copies', () {
    expect(File('assets/seed/assistant_copy.json').readAsStringSync(), File('../seed/assistant_copy.json').readAsStringSync());
    expect(File('assets/seed/demo_seed.json').readAsStringSync(), File('../seed/demo_seed.json').readAsStringSync());
  });

  test('Dart assistant == Python assistant on ${fixtures.length} fixtures', () {
    var checked = 0;
    for (final f in fixtures) {
      final lines = [
        for (final l in f['lines'] as List)
          Line(l[0], byId[l[0]]!['name'], l[1], l[2], byId[l[0]]!['price_pkr'], byId[l[0]]!['cod_eligible']),
      ];
      final subtotal = lines.fold<int>(0, (a, l) => a + l.unitPricePkr * l.quantity);
      final now = DateTime.parse('${f['now']}Z');
      final ex = f['existing_discount'] as List?;
      final r = rules.answer(
        f['question'],
        AssistantContext(
          storeName: 'UrbanThread PK',
          firstName: 'Ayesha',
          city: f['city'],
          lines: lines,
          subtotalPkr: subtotal,
          policy: Map<String, dynamic>.from(seed['policy']),
          settings: Map<String, dynamic>.from(seed['settings']),
          catalog: catalog,
          nowLocal: now,
          existingDiscount: ex == null ? null : (ex[0] as String, ex[1] as int),
          candidateCode: 'CC-TEST',
        ),
      );
      final e = f['expected'];
      final where = '[${f['case']} @ ${f['now']}] "${f['question']}"';
      expect(r.intent, e['intent'], reason: where);
      expect(r.language, e['language'], reason: where);
      expect(r.action, e['action'], reason: where);
      expect(r.text, e['text'], reason: where);
      expect(r.confidence, closeTo((e['confidence'] as num).toDouble(), 1e-9), reason: where);
      checked++;
    }
    expect(checked, fixtures.length);
  });
}
